import axios from 'axios';

import {
  fetchMyFollowers
  } from '../actions/myFollowersSearchActions'
 
import {
  fetchSentMessages
  } from '../actions/sentMessagesSearchActions'
  
import {
  fetchReceivedMessages
  } from '../actions/receivedMessagesSearchActions'

import {
  fetchRecentCommentersSearches
  } from '../actions/commentersSearchActions'

import {
  fetchRecentFollowersSearches
  } from '../actions/followersSearchActions'
  

export function handleSignupChange(event, context) {
        
        const { name, value } = event.target
        
        if (name === 'scUsername') {
            context.dispatch({
                type: "SIGNUP_USERNAME_CHANGE",
                scUsername: value
            })
        } else  if (name === 'scPassword') {
            context.dispatch({
                type: "SIGNUP_PASSWORD_CHANGE",
                scPassword: value
            })
        }
        
        if(context.state.scUsername && context.state.scUsername.length > 0 && context.state.scPassword && context.state.scPassword.length > 0) {
            context.dispatch({
                type: "SIGNUP_SUBMIT_ENABLE"
          })
        } else {
            context.dispatch({
                type: "SIGNUP_SUBMIT_DISABLE"
          })
        }

          

}


export function handleSignupSubmit(event, context) {

    context.dispatch({
         type: "SIGNUP_SUBMITTED"
       });
           
        axios({
            method: 'post',
            url: 'https://scbm.amfdev.co.uk/api/signup/',
            headers: {
                "X-Request-App": "scbm"
                },
            data: {
              scUsername: context.state.scUsername,
              scPassword: context.state.scPassword
            }
            })
            .then(json => catchSignupUserAlreadyExists(json.data, context.dispatch))
            .then(json => catchSignupScLoginError(json, context.dispatch))
            .then(json => catchSignupCookieError(json, context.dispatch))
            .then(json => catchSignupUserCreatedError(json, context.dispatch))
            .then(json => doSignupSuccess(json, context.dispatch))
            .then(json => context.dispatch(fetchReceivedMessages()))
            .then(json => context.dispatch(fetchSentMessages()))
            .then(json => context.dispatch(fetchMyFollowers()))
            .then(json => context.dispatch(fetchRecentCommentersSearches()))
            .then(json => context.dispatch(fetchRecentFollowersSearches()))
            .catch(error => {

                if (error.response) {   
                      context.dispatch({
                          type: "SIGNUP_UNKNOWN_ERROR"
                      })  
                }
            });
                  
    
}


function catchSignupUserAlreadyExists(json, dispatch) {
    //console.log('catchSignupScLoginError')
    //console.log(json)
    if (json.userAlreadyExists) {
        dispatch({
                type: "SIGNUP_USER_ALREADY_EXISTS"
              })
        throw Error(json.error);
    }
    
  return json;
}


function catchSignupScLoginError(json, dispatch) {
    //console.log('catchSignupScLoginError')
    if (!json.scLoginSuccess) {
        dispatch({
                type: "SIGNUP_SC_LOGIN_ERROR"
              })
        throw Error(json.error);
    }
    
  return json;
}


function catchSignupCookieError(json, dispatch) {
    //console.log('catchSignupCookieError')
    if (!json.scCookiesValid) {
        dispatch({
                type: "SIGNUP_COOKIE_ERROR"
              })
        throw Error(json.error);
    }
    
  return json;
}


function catchSignupUserCreatedError(json, dispatch) {
    //console.log('catchSignupUserCreatedError')
    if (!json.userCreated) {
        dispatch({
                type: "SIGNUP_USER_CREATED_ERROR"
              })
        throw Error(json.error);
    }
    
  return json;
}


function doSignupSuccess(json, dispatch) {
    //console.log('doSignupSuccess')
        dispatch({
                type: "SIGNUP_SUCCESS",
                userData: json.userData,
                userSettings: JSON.parse(json.userData.userSettings)
              })
  return json;
}


export function handleSignupSwitchToLogin(event, context) {

        context.dispatch({
                type: "SIGNUP_SWITCH_TO_LOGIN"
        })
        
  
}
